static void fftr4_kernel(auto d, MFFTELEM *__restrict__ Y,
                         MFFTELEM *__restrict__ X, const int64_t stride,
                         int64_t k_limit, int64_t base_x, int64_t step_x,
                         int64_t base_y, int64_t step_y) noexcept {
  for (int64_t k = 0; k < k_limit; k += 2) {
    const auto v0 = LoadComplexGroup(d, &X[base_x + k * stride], stride);
    const auto v1 =
        LoadComplexGroup(d, &X[base_x + k * stride + step_x], stride);
    const auto v2 =
        LoadComplexGroup(d, &X[base_x + k * stride + step_x * 2], stride);
    const auto v3 =
        LoadComplexGroup(d, &X[base_x + k * stride + step_x * 3], stride);
    const auto t24 = hn::Add(v0, v2);
    const auto t25 = hn::Sub(v0, v2);
    const auto t26 = hn::Add(v1, v3);
    const auto s4 = hn::ComplexConj(hn::Reverse2(d, hn::Sub(v1, v3)));
    StoreComplexGroup(d, hn::Add(t24, t26), &Y[base_y + k * stride], stride);
    StoreComplexGroup(d, hn::Sub(t24, t26),
                      &Y[base_y + k * stride + 2 * step_y], stride);
    StoreComplexGroup(d, hn::Add(t25, s4), &Y[base_y + k * stride + step_y],
                      stride);
    StoreComplexGroup(d, hn::Sub(t25, s4), &Y[base_y + k * stride + 3 * step_y],
                      stride);
  }
}

