template <>
void fftr13<false>(MFFTELEM **YY, MFFTELEM **XX, const int64_t N,
                   const int32_t e1, const int64_t bp, const int64_t stride,
                   int32_t flags) noexcept {
  // seed = 959539012
  MFFTELEM *__restrict__ Y = *YY + bp;
  MFFTELEM *__restrict__ X = *XX + bp;
  int64_t l = N / 13;
  int64_t m = 1;
  MFFTELEM *__restrict__ tmp;
  const std::complex<double> *__restrict__ W =
      reinterpret_cast<const std::complex<double> *>(COS_SIN_13);
  for (int32_t t = 0; t < e1; t++) {
    const auto step_x = stride * m * l;
    const auto step_y = stride * m;
    if (m > 1)
      fftr13_kernel(sp_4, Y, X, stride, m - 1, 0, step_x, 0, step_y);
    if (m & 1)
      fftr13_kernel(sp_2, Y, X, stride, 1, stride * (m - 1), step_x,
                    stride * (m - 1), step_y);
    const auto w_l = hn::Load(dp_2, CCDPTR(&W[e1 - t - 1]));
    auto w = hn::Load(dp_2, CCDPTR(&W[0]));
    for (int64_t j = 1; j < l; j++) {
      w = hn::MulComplex(w, w_l);
      auto w_f = Convert(sp_4, dp_2, w);
      const auto w2_f = hn::MulComplex(w_f, w_f);
      const auto w3_f = hn::MulComplex(w_f, w2_f);
      const auto w4_f = hn::MulComplex(w2_f, w2_f);
      const auto w5_f = hn::MulComplex(w2_f, w3_f);
      const auto w6_f = hn::MulComplex(w3_f, w3_f);
      const auto w7_f = hn::MulComplex(w3_f, w4_f);
      const auto w8_f = hn::MulComplex(w4_f, w4_f);
      const auto w9_f = hn::MulComplex(w4_f, w5_f);
      const auto w10_f = hn::MulComplex(w5_f, w5_f);
      const auto w11_f = hn::MulComplex(w5_f, w6_f);
      const auto w12_f = hn::MulComplex(w6_f, w6_f);
      const auto base_x = stride * (j * m);
      const auto base_y = stride * (13 * j * m);
      if (m > 1)
        fftr13_kernel_w(sp_4, Y, X, stride, m - 1, base_x, step_x, base_y,
                        step_y, w_f, w2_f, w3_f, w4_f, w5_f, w6_f, w7_f, w8_f,
                        w9_f, w10_f, w11_f, w12_f);
      if (m & 1)
        fftr13_kernel_w(
            sp_2, Y, X, stride, 1, base_x + stride * (m - 1), step_x,
            base_y + stride * (m - 1), step_y, hn::LowerHalf(w_f),
            hn::LowerHalf(w2_f), hn::LowerHalf(w3_f), hn::LowerHalf(w4_f),
            hn::LowerHalf(w5_f), hn::LowerHalf(w6_f), hn::LowerHalf(w7_f),
            hn::LowerHalf(w8_f), hn::LowerHalf(w9_f), hn::LowerHalf(w10_f),
            hn::LowerHalf(w11_f), hn::LowerHalf(w12_f));
    }
    l /= 13;
    m *= 13;
    tmp = X;
    X = Y;
    Y = tmp;
  }
  *XX = Y - bp;
  *YY = X - bp;
}


