      auto w_f = Convert(sp_4, dp_2, w);
      const auto w2_f = hn::MulComplex(w_f, w_f);
      const auto w3_f = hn::MulComplex(w_f, w2_f);
      const auto w4_f = hn::MulComplex(w2_f, w2_f);
      const auto w5_f = hn::MulComplex(w2_f, w3_f);
      const auto w6_f = hn::MulComplex(w3_f, w3_f);
      const auto w7_f = hn::MulComplex(w3_f, w4_f);
      const auto w8_f = hn::MulComplex(w4_f, w4_f);
      const auto w9_f = hn::MulComplex(w4_f, w5_f);
      const auto w10_f = hn::MulComplex(w5_f, w5_f);
      const auto w11_f = hn::MulComplex(w5_f, w6_f);
      const auto w12_f = hn::MulComplex(w6_f, w6_f);
      const auto w13_f = hn::MulComplex(w6_f, w7_f);
      const auto w14_f = hn::MulComplex(w7_f, w7_f);
      const auto w15_f = hn::MulComplex(w7_f, w8_f);
      const auto w16_f = hn::MulComplex(w8_f, w8_f);
      const auto w17_f = hn::MulComplex(w8_f, w9_f);
      const auto w18_f = hn::MulComplex(w9_f, w9_f);
